import { NgModule } from '@angular/core';
import { BrowserModule } from '@angular/platform-browser';

import { AppRoutingModule } from './app-routing.module';
import { AppComponent } from './app.component';
import { DashboardComponent } from './dashboard/dashboard.component';
import { SidebarComponent } from './sidebar/sidebar.component';
import { NavbarComponent } from './navbar/navbar.component';
import { JobsComponent } from './jobs/jobs.component';
import { CountComponent } from './count/count.component';
import { JoobseekerComponent } from './joobseeker/joobseeker.component';
import { JobprovidersComponent } from './jobproviders/jobproviders.component';
import { NewresgisterationComponent } from './newresgisteration/newresgisteration.component';
import { MyprofileComponent } from './myprofile/myprofile.component';
import { MessagesComponent } from './messages/messages.component';
import { SettingsComponent } from './settings/settings.component';
import { LogoutComponent } from './logout/logout.component';

@NgModule({
  declarations: [
    AppComponent,
    DashboardComponent,
    SidebarComponent,
    NavbarComponent,
    JobsComponent,
    CountComponent,
    JoobseekerComponent,
    JobprovidersComponent,
    NewresgisterationComponent,
    MyprofileComponent,
    MessagesComponent,
    SettingsComponent,
    LogoutComponent
  ],
  imports: [
    BrowserModule,
    AppRoutingModule
  ],
  providers: [],
  bootstrap: [AppComponent]
})
export class AppModule { }
